@layer hj.components {
  /* Customise: --hj-separator-color · --hj-separator-inset · --hj-separator-space */
  .hj-separator {
    flex: none;
    border: 0;
    margin: var(--hj-separator-space, 0) 0;
    background: var(--hj-separator-color, var(--hj-line));
  }
  .hj-separator[data-orientation='horizontal'] {
    width: 100%;
    height: var(--hj-hairline);
  }
  .hj-separator[data-orientation='vertical'] {
    width: var(--hj-hairline);
    height: auto;
    align-self: stretch;
    margin: 0 var(--hj-separator-space, 0);
  }
  .hj-separator[data-variant='inset'][data-orientation='horizontal'] {
    width: auto;
    margin-left: var(--hj-separator-inset, calc(72px * var(--hj-density)));
  }

  /* Labelled: a word sitting in the rule. The element stays a rule; the line is drawn either side. */
  .hj-separator[data-label] {
    display: flex;
    align-items: center;
    gap: calc(12px * var(--hj-density));
    height: auto;
    background: none;
    color: var(--hj-fg-mute);
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
  }
  .hj-separator[data-label]::before,
  .hj-separator[data-label]::after {
    content: '';
    flex: 1;
    height: var(--hj-hairline);
    background: var(--hj-separator-color, var(--hj-line));
  }
  .hj-separator-label {
    flex: none;
  }
}

'use client';
import { Separator as Base } from '@base-ui/react/separator';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

/** Props hanji adds to Base UI's Separator. */
export interface SeparatorOwnProps {
  /** full = edge to edge · inset = starts where row text starts (72px by default). */
  variant?: 'full' | 'inset';
  /** A short word in the middle of the rule, e.g. “or”. Horizontal only. */
  label?: React.ReactNode;
}

export interface SeparatorProps extends SeparatorOwnProps, Base.Props {}

/**
 * A hairline between groups. hanji separates with rules, not boxes — depth is a paper step and a
 * hairline, never a shadow.
 *
 * @example
 * <Separator />
 * <Separator variant="inset" />
 * <Separator label="or" />
 */
export function Separator(props: SeparatorProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    variant = 'full',
    label,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Separator', props);
  const hasLabel = label !== undefined && label !== null && label !== false;
  return (
    <Base
      {...rest}
      data-variant={variant}
      data-label={hasLabel ? '' : undefined}
      className={cls(config, 'Separator', 'hj-separator', className)}
    >
      {hasLabel ? (
        <span className={config.unstyled ? undefined : 'hj-separator-label'}>{label}</span>
      ) : (
        children
      )}
    </Base>
  );
}
